/* 知夏 · 变量结构
 *
 * 这张卡的玩法是挂机式：妹妹自己在这里活着，玩家离开的那段时间由脚本按**真实时间**折算成她的状态变化。
 * 所以变量分两类：
 * - 会随时间自己变的：妹妹的饥饿、心情、健康，家里的钱
 * - 只由面板动作改的：物品、衣柜
 *
 * 换算规则与上限写在 `脚本/离线结算.ts`，这里只管结构、开局值与合法区间。
 *
 * 前缀约定（MVU 规定）：
 * - 无前缀：AI 可见可更新
 * - `_` 前缀：AI 可见不可更新，只由脚本写
 * - `$` 前缀：AI 看不见，只由脚本写（记账用的都在这里）
 *
 * 数值一律写成 `z.coerce.number().prefault(开局值).transform(钳制)`。
 * 顺序不能反：prefault 是给输入补默认值的，挂在 transform 后面就永远不会生效。
 *
 * 不 import zod 与 lodash：酒馆运行环境自带 `z` 与 `_`。
 */
/** 开局年龄固定为 8 岁，不做选择。挂机结算也用它当推算的基准。 */
export const 起始年龄 = 8;
/** 阶段跟着年龄走（1 到 4）。年龄不再由玩家选。 */
export function 取阶段(年龄) {
    if (年龄 < 7)
        return 1;
    if (年龄 < 9)
        return 2;
    if (年龄 < 12)
        return 3;
    return 4;
}
/** 时段表。只用来显示与让正文对齐，不参与挂机结算。 */
export const 时段表 = ['清晨', '上午', '下午', '傍晚', '夜里', '深夜'];
/** 四个季节。服装按季上架，所以季节是一个真变量。 */
export const 季节表 = ['春', '夏', '秋', '冬'];
/**
 * 开局那一天：第 1 年 3 月 1 日，春。
 * 年、月、日、季节、总天数都由脚本按真实时间推，人和 AI 都不改它们。
 * 这几个常量要和 `脚本/离线结算.ts` 里的 `日历()` 一致。
 */
export const 开局月 = 3;
export const 开局日 = 1;
const 结构 = z.object({
    时间: z
        .object({
        年: z.coerce.number().prefault(1),
        月: z.coerce
            .number()
            .prefault(开局月)
            .transform(v => _.clamp(v, 1, 12)),
        日: z.coerce
            .number()
            .prefault(开局日)
            .transform(v => _.clamp(v, 1, 30)),
        时段: z.string().prefault('傍晚'),
        季节: z.string().prefault('春'),
        总天数: z.coerce.number().prefault(0),
    })
        .prefault({}),
    钱: z.coerce.number().prefault(320),
    /** 攒下的力气。玩小游戏要花它，睡觉与吃饭回它。 */
    哥哥: z
        .object({
        体力: z.coerce
            .number()
            .prefault(80)
            .transform(v => _.clamp(v, 0, 100)),
        今日已打工: z.coerce
            .number()
            .prefault(0)
            .transform(v => _.clamp(v, 0, 1)),
    })
        .prefault({}),
    /** 挣钱的进度：各处的熟练度与做过几次。只由面板写。 */
    进度: z
        .object({
        熟练: z
            .record(z.string().describe('场地名'), z.coerce.number().transform(v => _.clamp(v, 0, 100)))
            .prefault({ 工地: 0, 后厨: 0, 仓库: 0, 夜市: 0 }),
        次数: z
            .record(z.string().describe('场地名'), z.coerce.number().prefault(0))
            .prefault({ 工地: 0, 后厨: 0, 仓库: 0, 夜市: 0 }),
        上次: z.string().prefault(''),
    })
        .prefault({}),
    /**
    /**
     * 今天的互动余量。像桌面养成那样，一天的次数很少，用完就得等真实时间过一天。
     * 只有喂她、给她用药、买东西、出工这四件动手的事计入；
     * 「陪她」不走面板，靠正文里的对话与相处，所以不在这里计数。
     * 日子推进只由真实时间负责：脚本发现跨了天就把这几个计数清零。
     */
    今日: z
        .object({
        日期: z.string().prefault(''),
        喂过: z.coerce.number().prefault(0),
        药过: z.coerce.number().prefault(0),
        买过: z.coerce.number().prefault(0),
        出过工: z.coerce.number().prefault(0),
    })
        .prefault({}),
    妹妹: z
        .object({
        年龄: z.coerce
            .number()
            .prefault(起始年龄)
            .transform(v => _.clamp(v, 起始年龄, 16)),
        阶段: z.coerce
            .number()
            .prefault(取阶段(起始年龄))
            .transform(v => _.clamp(v, 1, 4)),
        饥饿: z.coerce
            .number()
            .prefault(70)
            .transform(v => _.clamp(v, 0, 100)),
        心情: z.coerce
            .number()
            .prefault(60)
            .transform(v => _.clamp(v, 0, 100)),
        健康: z.coerce
            .number()
            .prefault(90)
            .transform(v => _.clamp(v, 0, 100)),
        依赖: z.coerce
            .number()
            .prefault(40)
            .transform(v => _.clamp(v, 0, 100)),
        病症: z.string().prefault('无'),
    })
        .prefault({}),
    物品: z
        .record(z.string().describe('物品名'), z.object({
        数量: z.coerce.number().prefault(0),
        类别: z.string().prefault('其他'),
    }))
        .prefault({})
        .transform(表 => _.pickBy(表, 条目 => Number(条目?.数量) > 0)),
    衣柜: z
        .object({
        已购: z
            .record(z.string().describe('衣服名'), z.coerce.number())
            .prefault({ 旧毛衣: 1, 旧长裤: 1, 小学校服: 1 }),
        当前穿: z.string().prefault('旧毛衣'),
    })
        .prefault({}),
    /** 挂机记账：AI 看不到。时间戳是真实毫秒，用来算玩家离开了多久。 */
    $记账: z
        .object({
        上次时刻: z.coerce.number().prefault(0),
        上次结算: z.string().prefault(''),
        已结算次数: z.coerce.number().prefault(0),
    })
        .prefault({}),
});
export const Schema = 结构;
